          "how.ownerStep3Title": "Nabídka se zobrazí",
          "how.ownerStep4Text": "Když přijde žádost, v části Moje nabídky ji potvrdíte nebo odmítnete.",
          "how.ownerStep4Title": "Vyřídíte žádost",
          "how.ownerStep5Text": "Po zaplacení se zpřístupní kontakty. Při předání zadáte 6místný PIN od nájemce, zkontrolujete rezervaci a kliknete na „Předat věc“.",
          "how.ownerStep5Title": "Předáte věc",
          "how.ownerStep6Text": "Jakmile po ověření PINu potvrdíte předání věci, Rentulo ihned zadá Stripe pokyn k uvolnění vaší výplaty. Rentulo peníze nezadržuje. Jejich odeslání a připsání na bankovní účet následně zpracovává Stripe a banka, což může zejména při první výplatě trvat několik dní. Po vrácení věci potvrdíte vrácení. Dokončenou rezervaci najdete v Historii, kde můžete nájemce ohodnotit.",
          "how.ownerStep6Title": "Výplata, vrácení a hodnocení",
          "how.ownerTitle": "Chci nabídnout věc",
          "how.renterStep1Text": "Zadáte, co hledáte a kde se nacházíte.",
          "how.renterStep1Title": "Najděte věc",
          "how.renterStep2Text": "Podíváte se na cenu za den, lokalitu a popis. Volný termín ověříte v detailu.",
          "how.renterStep2Title": "Vyberete nabídku",
          "how.renterStep3Text": "Vyberete datum půjčení a datum vrácení.",
