          "contact.documentTitle": "Kontakt - Rentulo",
          "contact.eyebrow": "Kontakt",
          "contact.title": "Ako vám môžeme pomôcť?",
          "contact.intro": "Máte otázku k účtu, ponuke, rezervácii alebo fungovaniu Rentula? Napíšte nám a uveďte čo najpresnejšie, s čím potrebujete pomôcť.",
          "contact.supportKicker": "Podpora",
