          "contact.documentTitle": "Contact - Rentulo",
          "contact.eyebrow": "Contact",
          "contact.title": "How can we help?",
          "contact.intro": "Do you have a question about your account, a listing, a reservation or how Rentulo works? Write to us and describe as precisely as possible what you need help with.",
          "contact.supportKicker": "Support",
          "contact.supportTitle": "Customer support",
          "contact.supportText": "For questions about your account, listings, reservations, payments or technical issues, contact us by email.",
          "contact.emailLabel": "Email",
          "contact.privacyEmailLabel": "Data protection (GDPR)",
          "contact.phoneLabel": "Phone",
          "contact.toBeAdded": "To be added",
          "contact.testBadge": "Test version",
          "contact.operatorTitle": "Rentulo operator",
          "contact.operatorNotice": "The operator identification details will be added before the production launch. The fields below currently serve only as the prepared structure of this page.",
          "contact.companyLabel": "Company name",
