          "how.ownerStep5Text": "Nach der Zahlung werden die Kontaktdaten freigegeben. Bei der Übergabe gibst du die 6-stellige PIN des Mieters ein, prüfst die Reservierung und klickst auf „Gegenstand übergeben“.",
          "how.ownerStep5Title": "Gegenstand übergeben",
          "how.ownerStep6Text": "Sobald du die Übergabe nach der PIN-Prüfung bestätigst, weist Rentulo Stripe umgehend an, deine Auszahlung freizugeben. Rentulo hält das Geld nicht zurück. Die Überweisung und Gutschrift auf deinem Bankkonto werden anschließend von Stripe und deiner Bank abgewickelt. Besonders bei der ersten Auszahlung kann dies mehrere Tage dauern. Nach der Rückgabe bestätigst du die Rückgabe des Gegenstands. Die abgeschlossene Reservierung findest du im Verlauf, wo du den Mieter bewerten kannst.",
