          "contact.intro": "Haben Sie eine Frage zu Ihrem Konto, einem Angebot, einer Reservierung oder zur Funktionsweise von Rentulo? Schreiben Sie uns und beschreiben Sie möglichst genau, wobei Sie Hilfe benötigen.",
